@_mutmut_mutated(mutants_x__load_batch_sources__mutmut)
def _load_batch_sources(
    settings: CresmoSettings | None = None,
    explicit_manifest: Path | None = None,
    media_ingestion_port: MediaIngestionPort | None = None,
    lookback_days: int | None = None,
    channel_max_videos: int = 50,
    include_raw_lake: bool = True,
) -> list[BatchSource]:
    """Delegate batch source discovery to DiscoverBatchSourcesUseCase."""
    resolved_settings = settings or CresmoSettings()
    if media_ingestion_port is None:
        use_case = build_discover_batch_sources_use_case(settings=resolved_settings)
    else:
        use_case = DiscoverBatchSourcesUseCase(
            media_ingestion_port=media_ingestion_port,
            settings=resolved_settings,
        )
    query = BatchDiscoveryQuery(
        manifest_path=explicit_manifest,
        scan_raw=include_raw_lake,
        lookback_days=lookback_days,
        channel_max_videos=channel_max_videos,
    )
    return use_case.execute(query=query)


